-- Example artist biographies. Existing artists with the same names are not duplicated.
UPDATE `content`
SET `about` = CASE `companyname`
    WHEN 'The Weeknd' THEN 'Канадский певец и автор песен, соединяющий современный R&B, поп и электронное звучание. Его музыка часто строится на контрасте мелодичных припевов и мрачной кинематографичной атмосферы.'
    WHEN 'Playboi Carti' THEN 'Американский рэпер, связанный с экспериментальным трэп-звучанием и выразительной подачей. Его минималистичные вокальные фразы и резкие, насыщенные басом биты стали узнаваемой частью современной хип-хоп-сцены.'
    WHEN 'Kendrick Lamar' THEN 'Американский рэпер и автор песен, известный вниманием к истории, идентичности и жизни общества. В его творчестве сочетаются подробное повествование, смена музыкальных стилей и выразительная работа со словом.'
    WHEN 'Future' THEN 'Американский рэпер, чья мелодичная подача и атмосферные трэп-биты заметно повлияли на современный хип-хоп. В песнях он часто использует вокальные эффекты и сочетает рэп с напевными припевами.'
    WHEN 'Metro Boomin' THEN 'Американский продюсер и артист, создающий узнаваемые хип-хоп-биты с глубокими басами, синтезаторами и кинематографичными деталями. Известен совместной работой с исполнителями разных поколений рэп-сцены.'
    WHEN 'Drake' THEN 'Канадский рэпер, певец и автор песен, свободно соединяющий хип-хоп, R&B и поп. Его музыка часто строится на мелодичных припевках и личных историях об отношениях, успехе и сомнениях.'
    WHEN 'Yeat' THEN 'Американский рэпер с электронным, синтезаторным звучанием и энергичной вокальной манерой. В его треках трэп-ритмы сочетаются с необычными звуковыми эффектами и повторяющимися мелодическими мотивами.'
    WHEN 'Don Toliver' THEN 'Американский певец и рэпер, работающий на стыке мелодичного хип-хопа и R&B. Его узнаваемый высокий вокал и воздушные аранжировки создают атмосферное, легко запоминающееся звучание.'
    WHEN 'Tyler, The Creator' THEN 'Американский рэпер, продюсер и автор песен, который постоянно меняет музыкальные направления. В его работах хип-хоп соединяется с соулом, джазом и альтернативным попом, а продакшн часто полностью создан им самим.'
    WHEN 'Ye' THEN 'Американский рэпер, продюсер и дизайнер, известный интересом к экспериментам в хип-хопе и поп-музыке. Его звучание меняется от лаконичных семплов до электронных и хоровых аранжировок.'
    WHEN 'A$AP Rocky' THEN 'Американский рэпер и артист из Нью-Йорка, соединяющий хип-хоп с психоделическими и южными музыкальными влияниями. Визуальная эстетика, мода и режиссура клипов занимают заметное место в его творческом образе.'
    WHEN 'Radiohead' THEN 'Британская рок-группа, известная тем, что развивала своё звучание от альтернативного рока к смелым электронным и экспериментальным аранжировкам. В песнях группы сочетаются атмосферные мелодии и размышления о технологиях, одиночестве и переменах.'
    ELSE `about`
END
WHERE (`about` IS NULL OR `about` = '')
  AND `companyname` IN ('The Weeknd', 'Playboi Carti', 'Kendrick Lamar', 'Future', 'Metro Boomin', 'Drake', 'Yeat', 'Don Toliver', 'Tyler, The Creator', 'Ye', 'A$AP Rocky', 'Radiohead');

INSERT INTO `content`
    (`companyname`, `about`, `logo`, `industry`, `active`, `link`, `description`, `album`)
SELECT new_artist.`companyname`, new_artist.`about`, '', industry.`id`, 1, '', industry.`description`, ''
FROM (
    SELECT 'Ariana Grande' AS `companyname`, 'Американская певица и автор песен, известная выразительным вокалом. В её поп-звучании сочетаются R&B, танцевальная музыка и личные истории о любви, взрослении и уверенности в себе.' AS `about`, 'Поп и R&B' AS `category`
    UNION ALL
    SELECT 'SZA', 'Американская певица и автор песен, соединяющая альтернативный R&B, соул и поп. Её песни часто звучат как откровенный дневник о самооценке, отношениях и поиске своего места.', 'Поп и R&B'
    UNION ALL
    SELECT 'Billie Eilish', 'Американская певица и автор песен, прославившаяся камерным вокалом и атмосферным поп-звучанием. В её музыке соседствуют электронные детали, минималистичные аранжировки и необычные визуальные образы.', 'Альтернативная музыка'
    UNION ALL
    SELECT 'Travis Scott', 'Американский рэпер и продюсер, известный масштабным хип-хоп-звучанием, насыщенным эффектами, мелодичными припевами и атмосферными битами.', 'Хип-хоп'
    UNION ALL
    SELECT 'J. Cole', 'Американский рэпер, автор песен и продюсер. В его музыке сочетаются вдумчивые тексты, личные истории и традиционное хип-хоп-продюсирование.', 'Хип-хоп'
    UNION ALL
    SELECT 'Kaytranada', 'Канадский диджей и продюсер гаитянского происхождения. Его танцевальные инструменталы соединяют хаус, хип-хоп, фанковые ритмы и выразительный грув.', 'Продюсеры'
) AS new_artist
JOIN `industry` ON industry.`description` = new_artist.`category`
WHERE NOT EXISTS (
    SELECT 1 FROM `content` existing WHERE existing.`companyname` = new_artist.`companyname`
);
